<?php require_once __DIR__.'/../../includes/auth.php';require_login('admin');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/bookings/index.php');verify_csrf();$id=(int)($_POST['booking_id']??0);$st=post('status');$allowed=['Pending','Confirmed','Assigned','In Progress','Completed','Cancelled'];if(!in_array($st,$allowed,true)){flash('error','Invalid status.');redirect('admin/bookings/index.php');}$s=$pdo->prepare('SELECT booking_reference FROM bookings WHERE id=?');$s->execute([$id]);$ref=$s->fetchColumn();if(!$ref){flash('error','Booking not found.');redirect('admin/bookings/index.php');}$s=$pdo->prepare('UPDATE bookings SET status=?,updated_at=NOW() WHERE id=?');$s->execute([$st,$id]);log_activity('Booking status change','Booking '.$ref.' changed to '.$st);flash('success','Booking status updated.');redirect('admin/bookings/view.php?id='.$id);